  {
    "statement": "Evidence suggests several cost-effective methods for dietary enrichment in captive primates.",
    "citations": []
  },
  {
    "statement": "Scattering food throughout an enclosure is a particularly effective method for primate enrichment.",
    "citations": [
      "1315"
    ]
  },
  {
    "statement": "Studies show that scattering food increases feeding and exploratory behaviors in rhesus macaques.",
    "citations": [
      "1315"
    ]
  },
  {
    "statement": "Scattering food has been shown to reduce abnormal behaviors in chimpanzees.",
    "citations": [
      "1315"
    ]
  },
  {
    "statement": "Scattering food can lead to decreased aggression in lemurs.",
    "citations": [
      "1315"
    ]
  },
  {
    "statement": "Scattering food has resulted in increased foraging and activity levels in gorillas.",
    "citations": [
