  },
  {
    "statement": "Feeding primates in social groups proves beneficial for the animals.",
    "citations": [
      "1343"
    ]
  },
  {
    "statement": "Monkeys complete enrichment tasks faster when with groupmates.",
    "citations": [
      "1343"
    ]
